return $input.all().map(item => {
  let parsed = {};

  try {
    // Try to parse the 'output' string as JSON
    parsed = JSON.parse(item.json.output);
  } catch (e) {
    // If parsing fails, keep it as raw string
    parsed = { error: "Invalid JSON string", raw: item.json.output };
  }

  return {
    json: {output:{
      // Include parsed JSON dynamically
      ...parsed}
    }
  };
});

return $input.all().map((item, idx) => {
  const raw = item.json.output;

  // Function to safely parse a JSON-like string
  function parseJsonLike(str) {
    const result = {};
    try {
      // Remove surrounding quotes if any
      let s = str.trim();
      if (s.startsWith('"') && s.endsWith('"')) {
        s = s.slice(1, -1);
      }

      // Normalize smart quotes
      s = s.replace(/[“”]/g, '"');

      // Remove non-breaking spaces
      s = s.replace(/\u00A0/g, ' ');

      // Remove trailing commas
      s = s.replace(/,(\s*[}\]])/g, '$1');

      // Match simple key-value pairs
      const keyValueRegex = /"([^"]+)"\s*:\s*(\[[^\]]*\]|\{[^\}]*\}|".*?"|[^,}\]]+)/g;
      let match;
      while ((match = keyValueRegex.exec(s)) !== null) {
        let key = match[1];
        let value = match[2].trim();

        // Remove quotes around value if string
        if (value.startsWith('"') && value.endsWith('"')) {
          value = value.slice(1, -1);
        }

        result[key] = value;
      }

      return result;
    } catch (e) {
      return {
        error: 'Could not parse JSON-like string',
        raw: str,
        index: idx,
        message: e.message
      };
    }
  }

  const parsed = parseJsonLike(raw);

  return { json: { output: parsed } };
});
